let storeAgentPaused=false;
function selectStoreAgent(key){const data=storeAgentData[key];if(!data)return;const noIncident=['office','mall','riverside'].includes(key);const needsApproval=['market','campus','community','hospital'].includes(key);document.querySelectorAll('[data-store-agent]').forEach(button=>button.classList.toggle('active',button.dataset.storeAgent===key));document.querySelector('#agentQueue').textContent=data.queue;document.querySelector('#agentQueueNote').textContent=data.queueNote;document.querySelector('#agentLongest').textContent=data.longest;document.querySelector('#agentLongestNote').textContent=data.longestNote;document.querySelector('#agentLoad').textContent=data.load;document.querySelector('#agentLoadNote').textContent=data.loadNote;document.querySelector('#agentTablet').textContent=data.tablet;document.querySelector('#incidentTime').textContent=data.time;document.querySelector('#incidentTitle').textContent=data.title;document.querySelector('#incidentDetail').textContent=data.detail;document.querySelector('.incident-level>span').textContent=data.level;document.querySelector('.incident-level small').textContent=data.kind;const incident=document.querySelector('#primaryIncident');incident.classList.toggle('resolved',noIncident);document.querySelector('#incidentStatus').textContent=noIncident?'無異常':needsApproval?'需核准':'待處理';document.querySelector('#applyStoreAction').disabled=noIncident;document.querySelector('#applyStoreAction').textContent=noIncident?'無需處理':needsApproval?'建立核准草稿':'套用低風險處理'}
document.querySelectorAll('[data-store-agent]').forEach(button=>button.addEventListener('click',()=>selectStoreAgent(button.dataset.storeAgent)));
document.querySelector('#pauseStoreAgent')?.addEventListener('click',()=>{storeAgentPaused=!storeAgentPaused;const live=document.querySelector('.agent-live');live.classList.toggle('paused',storeAgentPaused);document.querySelector('#storeAgentState').textContent=storeAgentPaused?'已暫停監看':'即時監看中';document.querySelector('#pauseStoreAgent').textContent=storeAgentPaused?'恢復':'暫停';window.toast?.(storeAgentPaused?'門市 Agent 已暫停':'門市 Agent 已恢復監看')});
document.querySelector('#applyStoreAction')?.addEventListener('click',()=>{const active=document.querySelector('[data-store-agent].active')?.dataset.storeAgent;if(['market','campus','community','hospital'].includes(active)){window.toast?.('已建立調撥或效期處理草稿，等待店長核准');document.querySelector('#incidentStatus').textContent='待核准';return}const incident=document.querySelector('#primaryIncident');incident.classList.add('resolved');document.querySelector('#incidentStatus').textContent='已處理';document.querySelector('#incidentTitle').textContent='已更新等待時間並通知吧台';document.querySelector('#incidentDetail').textContent='顧客預估等待時間已更新；吧台已收到提醒，未變更訂單內容。';document.querySelector('#applyStoreAction').disabled=true;document.querySelector('#applyStoreAction').textContent='已執行';window.toast?.('門市監控 Agent 已完成低風險處理')});
document.querySelector('#simulateStorePeak')?.addEventListener('click',()=>{const section=document.querySelector('#storeAgentSection');section.classList.add('peak-mode');document.querySelector('#agentQueue').textContent='9 杯';document.querySelector('#agentQueueNote').textContent='5 分鐘內 +6 杯';document.querySelector('#agentLongest').textContent='11:08';document.querySelector('#agentLongestNote').textContent='超過承諾 6:08';document.querySelector('#agentLoad').textContent='94%';document.querySelector('#agentLoadNote').textContent='已達尖峰';document.querySelector('#incidentTime').textContent='剛剛・尖峰事件';document.querySelector('#incidentTitle').textContent='大量訂單湧入，3 杯可能超時';document.querySelector('#incidentDetail').textContent='門市監控 Agent 建議將網路點單等待時間由 5 分鐘調整為 12 分鐘，並提醒吧台先完成 3 張早到期訂單。';document.querySelector('#primaryIncident').classList.remove('resolved');document.querySelector('#incidentStatus').textContent='新異常';document.querySelector('#applyStoreAction').disabled=false;document.querySelector('#applyStoreAction').textContent='套用低風險處理';document.querySelector('#simulateStorePeak').textContent='已模擬尖峰事件';window.toast?.('已建立尖峰異常，等待門市監控 Agent 處理')});
